:root {
  --ink: #17233a;
  --muted: #66738a;
  --paper: #ffffff;
  --line: #dbe3ef;
  --navy: #203b72;
  --blue: #3974d8;
  --pale-blue: #edf4ff;
  --mint: #dff5e9;
  --green: #237a55;
  --amber: #eeb64b;
}

* {
  box-sizing: border-box;
}

.uplink-card {
  width: 480px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 15px 18px;
  background: var(--navy);
  color: var(--paper);
}

.title-block {
  display: flex;
  align-items: center;
  gap: 10px;
}

.orbit-mark {
  display: grid;
  width: 30px;
  height: 30px;
  place-items: center;
  border: 1px solid var(--blue);
  border-radius: 50%;
  color: var(--amber);
  font-size: 22px;
}

.eyebrow,
.panel-label {
  margin: 0;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.1px;
}

.eyebrow {
  color: var(--pale-blue);
}

h1 {
  margin: 2px 0 0;
  font-size: 19px;
  line-height: 1.1;
}

.status {
  padding: 5px 8px;
  border-radius: 999px;
  background: var(--mint);
  color: var(--green);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.8px;
}

.window-grid {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
}

.time-panel,
.channel-panel {
  padding: 15px 18px;
}

.time-panel {
  background: var(--pale-blue);
  border-right: 1px solid var(--line);
}

.panel-label {
  color: var(--muted);
}

.time {
  margin: 7px 0 2px;
  color: var(--navy);
  font-size: 28px;
  font-weight: 800;
  line-height: 1;
}

.time span {
  font-size: 11px;
  letter-spacing: 0.5px;
}

.date {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
}

.channel-list {
  display: grid;
  gap: 7px;
  margin: 8px 0 0;
  padding: 0;
  list-style: none;
}

.channel-list li {
  display: grid;
  grid-template-columns: 8px 1fr auto;
  align-items: center;
  gap: 7px;
  color: var(--ink);
  font-size: 12px;
}

.channel-list strong {
  color: var(--muted);
  font-size: 10px;
}

.dot {
  width: 7px;
  height: 7px;
  border: 1px solid var(--amber);
  border-radius: 50%;
}

.dot.active {
  background: var(--green);
  border-color: var(--green);
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 18px;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 11px;
}

button {
  padding: 6px 10px;
  border: 1px solid var(--blue);
  border-radius: 7px;
  background: var(--paper);
  color: var(--blue);
  font-size: 11px;
  font-weight: 700;
}
